function Button({children,secondary=false,danger=false,...props}:React.ButtonHTMLAttributes<HTMLButtonElement>&{secondary?:boolean;danger?:boolean}){return <button className={`button ${secondary?'secondary':''} ${danger?'danger':''}`} {...props}>{children}</button>;}
