  function confirmDelete(title:string,fn:()=>Promise<void>){setConfirm({title,text:'Zielserver: '+current?.name+'. Diese Änderung wird gespeichert. Änderungen an Hosts und Regeln werden erst nach dem Anwenden der Konfiguration aktiv.',danger:true,fn});}
  async function saveDraft(){const result=await api(`/instances/${selected}/revisions`,'POST',{config,base_hash:hash,message});setRev(result.id);setRevisions(await api(`/instances/${selected}/revisions`));return result.id;}
  if(checking)return <div className="loading-screen"><Loader2 className="spin"/> HAProxy Control wird geladen</div>;
  if(!user)return <Login onLogin={r=>{csrf=r.csrf;setUser(r.user);setToast(null);}}/>;
  if(user.must_change_password)return <PasswordScreen onDone={()=>{setUser(null);csrf='';}}/>;
