  const total=(key:keyof Stats)=>online.length?online.reduce((sum,i)=>sum+Number(i.stats?.[key]||0),0):undefined;
  const filteredHosts=doc.hosts.filter(h=>h.domain.includes(search)||h.servers.some(s=>s.address.includes(search)));
