    {confirm&&<Modal title={confirm.title} onClose={()=>!busy&&setConfirm(null)}><p className="modal-copy">{confirm.text}</p><div className="modal-actions"><Button secondary disabled={busy} onClick={()=>setConfirm(null)}>Abbrechen</Button><Button danger={confirm.danger} disabled={busy} onClick={()=>run(async()=>{await confirm.fn();setConfirm(null);})}>{busy?<Loader2 size={16} className="spin"/>:<Check size={16}/>}Bestätigen</Button></div></Modal>}
