    {modal==='imported-route'&&importedRouteEdit&&modalTarget&&<Modal wide title={importedRouteIndex===null?'Domain-Zuordnung hinzufügen':'Domain-Zuordnung bearbeiten'} onClose={()=>setModal(null)}><ImportedRouteForm certs={certs} initial={importedRouteEdit} groups={authDirectory?.groups||[]} fronts={doc.imported_route_frontends||Array.from(new Set((doc.imported_routes||[]).map(r=>r.frontend)))} backends={[...(doc.imported_backends||[]),...(doc.backends||[]).map(b=>({...b,servers:b.servers.map((s,i)=>({...s,name:'srv_'+(i+1)}))}))]} busy={busy} onClose={()=>setModal(null)} onSave={async value=>{await saveImportedFields({imported_routes:importedRouteIndex===null?[...(doc.imported_routes||[]),value]:(doc.imported_routes||[]).map((r,i)=>i===importedRouteIndex?value:r)});setModal(null);notify('Domain und Website-Zugang im Entwurf gespeichert.');}} /></Modal>}
    {modal==='agent-update'&&<Modal wide title="Agent aktualisieren" onClose={()=>setModal(null)}><div className="form-body"><p>Führe diesen Befehl auf dem HAProxy-Host aus. Er aktualisiert den bestehenden systemd-Agenten und startet ihn neu. Profile, Zugriffstokens und HAProxy-Konfigurationen bleiben erhalten.</p><textarea className="wizard-command" rows={7} readOnly aria-label="Agent-Aktualisierungsbefehl" value={updateCommand} onFocus={e=>e.target.select()}/><div className="modal-actions"><Button secondary onClick={()=>setModal(null)}>Schließen</Button><Button onClick={()=>run(async()=>{if(!navigator.clipboard)throw new Error('Bitte den markierten Befehl manuell kopieren.');await navigator.clipboard.writeText(updateCommand);},'Befehl kopiert.')}><Copy size={16}/>Kopieren</Button></div></div></Modal>}
    {modal==='host'&&<HostForm doc={doc} fronts={layout?.frontends.filter(f=>f.mode==='http')||[]} certs={certs} groups={authDirectory?.groups||[]} initial={hostEdit} busy={busy} onClose={()=>setModal(null)} onSave={value=>controlledSave(async()=>{await saveDoc({...doc,tls_enabled:doc.tls_enabled||doc.imported_config==null&&(value.frontend||'public_http')==='public_http'&&!!value.certificate,hosts:hostEdit?doc.hosts.map(h=>h.id===value.id?value:h):[...doc.hosts,value]});setModal(null);},'Proxy Host im Entwurf gespeichert.')} />}
