    {modal==='listeners'&&<ListenerForm doc={doc} busy={busy} onClose={()=>setModal(null)} onSave={value=>run(async()=>{await saveDoc(value);setModal(null);},'Listener-Einstellungen im Entwurf gespeichert.')} />}
    {(modal==='cert'||modal==='adopt-cert')&&<Modal wide title={modal==='adopt-cert'?'Vorhandenen LEGO-Auftrag übernehmen':"Let's-Encrypt-Zertifikat"} onClose={()=>setModal(null)}><CertificateRequestForm cap={cap} domains={Array.from(new Set([...doc.hosts.map(h=>h.domain),...(doc.imported_routes||[]).map(r=>r.domain)]))} busy={busy} adopt={modal==='adopt-cert'} onClose={()=>setModal(null)} onSave={value=>controlledSave(async()=>{await modalRequest(`/instances/${modalTarget!.id}/certificates/${modal==='adopt-cert'?'adopt-lego':'issue'}`,'POST',value);setCerts(await modalRequest(`/instances/${modalTarget!.id}/certificates`));setCap(await modalRequest(`/instances/${modalTarget!.id}/capabilities`));setModal(null);},'Zertifikat und ACME-Auftrag gespeichert.')}/></Modal>}
    {modal==='renewal-settings'&&renewalSettings&&<Modal title="Zeitplan für Zertifikatserneuerung" onClose={()=>setModal(null)}><RenewalSettingsForm initial={renewalSettings} busy={busy} onClose={()=>setModal(null)} onSave={value=>controlledSave(async()=>{setRenewalSettings(await modalRequest(`/instances/${modalTarget!.id}/certificates/renewal-settings`,'PUT',value));setModal(null);},'Zeitplan auf dem Agenten gespeichert.')}/></Modal>}
